def transform(grid):
    h, w = len(grid), len(grid[0])
    marker = next(v for v in set(sum(grid, []))
                  if v != 0 and all(any(x == v for x in row) for row in grid)
                  and sum(x == v for row in grid for x in row) >= h + w - 1)

    def bands(n, is_sep):
        out, start = [], 0
        for i in range(n):
            if is_sep(i):
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    rb = bands(h, lambda r: all(x == marker for x in grid[r]))
    cb = bands(w, lambda c: all(grid[r][c] == marker for r in range(h)))

    # Find the shape in any cell of the partition other than the color-key column.
    shape = None
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            if ci == 0:
                continue
            pts = [(r-r0, c-c0) for r in range(r0, r1)
                   for c in range(c0, c1) if grid[r][c] not in (0, marker)]
            if pts:
                shape = set(pts)
                break
        if shape:
            break

    # If the shape itself is drawn in the separator color, its cells are marker
    # cells within the tile, and can be inferred from the band containing the shape.
    if shape is None:
        for ri, (r0, r1) in enumerate(rb):
            for ci, (c0, c1) in enumerate(cb):
                if ci == 0:
                    continue
                pts = [(r-r0, c-c0) for r in range(r0, r1)
                       for c in range(c0, c1) if grid[r][c] == marker]
                # A tile with a pattern has marker cells beyond its border lines.
                if len(pts) > 0:
                    shape = set(pts)
                    break
            if shape:
                break

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                out[r][c] = marker

    for r0, r1 in rb:
        c0, c1 = cb[0]
        color = next((grid[r][c] for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] not in (0, marker)), 0)
        for a, b in cb:
            if shape:
                for dr, dc in shape:
                    if r0 + dr < r1 and a + dc < b:
                        out[r0 + dr][a + dc] = color
    return out
